-- Forward repair: qualify normalized component/document fields in M3-07 CTEs.

create or replace function public.materialize_sbom_composite_projection(p_organization_id uuid,p_review_id uuid)
returns void language plpgsql security definer set search_path=public,pg_temp as $$
begin
  delete from public.sbom_composite_conflicts where organization_id=p_organization_id and review_id=p_review_id;
  delete from public.sbom_composite_component_provenance where organization_id=p_organization_id and review_id=p_review_id;
  with base as (
    select i.source_id,i.document_id source_document_id,i.source_sha256,i.supplier_submission_id,c.id component_id,c.document_local_ref,c.normalized_name,c.normalized_version,c.canonical_purl,c.cpe,c.hashes,c.source_offset,coalesce(public.sbom_purl_package_identity(c.canonical_purl),'cpe:'||c.cpe,'unresolved:'||i.document_id::text||':'||c.document_local_ref) identity_key
    from public.sbom_composite_review_inputs i join public.sbom_components c on c.organization_id=i.organization_id and c.document_id=i.document_id where i.organization_id=p_organization_id and i.review_id=p_review_id
  ), fields as (select b.*,v.field_name,v.field_value from base b cross join lateral(values ('name',to_jsonb(b.normalized_name)),('canonicalPurl',to_jsonb(b.canonical_purl)),('canonicalCpe',to_jsonb(b.cpe)),('hashes',b.hashes)) v(field_name,field_value))
  insert into public.sbom_composite_conflicts(organization_id,review_id,identity_key,conflict_type,field_name,candidates)
  select p_organization_id,p_review_id,f.identity_key,'field_conflict',f.field_name,jsonb_agg(jsonb_build_object('component',jsonb_build_object('componentId',f.component_id,'sourceId',f.source_id,'documentId',f.source_document_id,'documentSha256',f.source_sha256,'sourceComponentRef',f.document_local_ref,'name',f.normalized_name,'version',f.normalized_version,'canonicalPurl',f.canonical_purl,'canonicalCpe',f.cpe,'supplierSubmissionId',f.supplier_submission_id),'value',case when f.field_value='null'::jsonb then null else f.field_value#>>'{}' end) order by f.source_id,f.source_offset,f.component_id) from fields f where f.identity_key not like 'unresolved:%' group by f.identity_key,f.field_name having count(distinct coalesce(f.normalized_version,''))<=1 and count(distinct coalesce(f.field_value::text,'null'))>1;
  with base as (select i.source_id,i.document_id source_document_id,i.source_sha256,i.supplier_submission_id,c.id component_id,c.document_local_ref,c.normalized_name,c.normalized_version,c.canonical_purl,c.cpe,c.hashes,c.source_offset,coalesce(public.sbom_purl_package_identity(c.canonical_purl),'cpe:'||c.cpe,'unresolved:'||i.document_id::text||':'||c.document_local_ref) identity_key from public.sbom_composite_review_inputs i join public.sbom_components c on c.organization_id=i.organization_id and c.document_id=i.document_id where i.organization_id=p_organization_id and i.review_id=p_review_id)
  insert into public.sbom_composite_conflicts(organization_id,review_id,identity_key,conflict_type,field_name,candidates)
  select p_organization_id,p_review_id,b.identity_key,'incompatible_version','version',jsonb_agg(jsonb_build_object('component',jsonb_build_object('componentId',b.component_id,'sourceId',b.source_id,'documentId',b.source_document_id,'documentSha256',b.source_sha256,'sourceComponentRef',b.document_local_ref,'name',b.normalized_name,'version',b.normalized_version,'canonicalPurl',b.canonical_purl,'canonicalCpe',b.cpe,'supplierSubmissionId',b.supplier_submission_id),'value',b.normalized_version) order by b.source_id,b.source_offset,b.component_id) from base b where b.identity_key not like 'unresolved:%' group by b.identity_key having count(distinct coalesce(b.normalized_version,''))>1;
  with base as (select i.source_id,i.document_id source_document_id,i.supplier_submission_id,c.id component_id,c.document_local_ref,c.normalized_version,c.canonical_purl,c.cpe,coalesce(public.sbom_purl_package_identity(c.canonical_purl),'cpe:'||c.cpe,'unresolved:'||i.document_id::text||':'||c.document_local_ref) identity_key from public.sbom_composite_review_inputs i join public.sbom_components c on c.organization_id=i.organization_id and c.document_id=i.document_id where i.organization_id=p_organization_id and i.review_id=p_review_id)
  insert into public.sbom_composite_component_provenance(organization_id,review_id,composite_component_ref,field_name,source_id,source_document_id,source_component_id,source_component_ref,supplier_submission_id)
  select p_organization_id,p_review_id,case when b.identity_key like 'unresolved:%' then 'component:'||b.source_document_id::text||':'||b.document_local_ref else 'component:'||encode(extensions.digest(b.identity_key||'@'||coalesce(b.normalized_version,''),'sha256'),'hex') end,v.field_name,b.source_id,b.source_document_id,b.component_id,b.document_local_ref,b.supplier_submission_id from base b cross join lateral(values('name'),('version'),('canonicalPurl'),('canonicalCpe'),('hashes')) v(field_name);
end;
$$;

create or replace function public.claim_sbom_composite_generation(p_organization_id uuid,p_worker_id uuid,p_lease_seconds integer)
returns table(outcome text,work jsonb) language plpgsql security definer set search_path=public,pg_temp as $$
declare r public.sbom_composite_reviews%rowtype; comps jsonb; selected_ids uuid[];
begin
  if p_worker_id is null or p_lease_seconds not between 15 and 900 then return query select 'invalid_request'::text,null::jsonb;return;end if;
  select * into r from public.sbom_composite_reviews x where x.organization_id=p_organization_id and x.status='processing' and (x.lease_expires_at is null or x.lease_expires_at<=now()) and (x.generated_source_id is not null or x.attempt_count<5) order by x.created_at,x.id for update skip locked limit 1;
  if not found then return query select 'empty'::text,null::jsonb;return;end if;
  update public.sbom_composite_reviews set lease_owner=p_worker_id,lease_expires_at=now()+make_interval(secs=>p_lease_seconds),attempt_count=attempt_count+case when generated_source_id is null then 1 else 0 end where organization_id=p_organization_id and id=r.id returning * into r;
  with b as (select i.source_id,i.document_id source_document_id,c.id component_id,c.document_local_ref,c.normalized_name,c.normalized_version,c.canonical_purl,c.hashes,c.source_offset,coalesce(public.sbom_purl_package_identity(c.canonical_purl),'cpe:'||c.cpe,'unresolved:'||i.document_id::text||':'||c.document_local_ref) identity_key,row_number() over(partition by coalesce(public.sbom_purl_package_identity(c.canonical_purl),'cpe:'||c.cpe,'unresolved:'||i.document_id::text||':'||c.document_local_ref) order by i.source_id,c.source_offset,c.id) rn from public.sbom_composite_review_inputs i join public.sbom_components c on c.organization_id=i.organization_id and c.document_id=i.document_id where i.organization_id=p_organization_id and i.review_id=r.id), d as (select x.identity_key,min(x.selected_source_component_id) filter(where x.conflict_type='incompatible_version') vc,min(x.selected_source_component_id) filter(where x.conflict_type='field_conflict') fc,bool_or(x.selected_source_component_id is null and x.resolution_reason is not null) excluded from public.sbom_composite_conflicts x where x.organization_id=p_organization_id and x.review_id=r.id group by x.identity_key), s as (select b.* from b left join d on d.identity_key=b.identity_key where not coalesce(d.excluded,false) and (b.component_id=coalesce(d.vc,d.fc,b.component_id)) and (coalesce(d.vc,d.fc) is not null or b.rn=1)) select coalesce(jsonb_agg(jsonb_build_object('componentRef',case when identity_key like 'unresolved:%' then 'component:'||source_document_id::text||':'||document_local_ref else 'component:'||encode(extensions.digest(identity_key||'@'||coalesce(normalized_version,''),'sha256'),'hex') end,'name',normalized_name,'version',normalized_version,'canonicalPurl',canonical_purl,'hashes',hashes,'sourceComponentId',component_id,'sourceId',source_id,'documentId',source_document_id) order by source_id,source_offset,component_id),'[]'::jsonb),coalesce(array_agg(component_id),'{}'::uuid[]) into comps,selected_ids from s;
  return query select 'claimed'::text,jsonb_build_object('reviewId',r.id,'actorId',r.created_by,'productId',r.product_id,'releaseId',r.release_id,'mergeRulesVersion',r.merge_rules_version,'generatedSourceId',r.generated_source_id,'components',comps,'dependencies','[]'::jsonb);
end;
$$;

revoke all on function public.materialize_sbom_composite_projection(uuid,uuid),public.claim_sbom_composite_generation(uuid,uuid,integer) from public,anon,authenticated;
grant execute on function public.materialize_sbom_composite_projection(uuid,uuid),public.claim_sbom_composite_generation(uuid,uuid,integer) to service_role;
